import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.XctAhZuT.js";const p=JSON.parse('{"title":"设置系统","description":"设置首页是导航型落地页：顶部个人卡 + 快捷设置 + 分区入口。设置项必须连接到运行时行为；尚未接入的实验项应禁用并标注状态。","frontmatter":{"description":"设置首页是导航型落地页：顶部个人卡 + 快捷设置 + 分区入口。设置项必须连接到运行时行为；尚未接入的实验项应禁用并标注状态。"},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1789373514000}'),i={name:"guide/settings.md"};function o(n,t,s,l,h,c){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="设置系统" tabindex="-1">设置系统 <a class="header-anchor" href="#设置系统" aria-label="Permalink to &quot;设置系统&quot;">​</a></h1><p>设置首页是导航型落地页：顶部个人卡 + 快捷设置 + 分区入口。设置项必须连接到运行时行为；尚未接入的实验项应禁用并标注状态。</p><h2 id="设置分区" tabindex="-1">设置分区 <a class="header-anchor" href="#设置分区" aria-label="Permalink to &quot;设置分区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分区</th><th>典型内容</th></tr></thead><tbody><tr><td>账号</td><td>昵称 / 头像 / 每日目标</td></tr><tr><td>学习</td><td>学习目标、每日提醒、<strong>Anki 区</strong>（每日新卡上限默认 20、每日复习上限默认 200、每日挑战 Anki 卡）</td></tr><tr><td>外观与声音</td><td>主题（亮/暗/跟随系统）、音效、触觉</td></tr><tr><td>可访问性</td><td>文本缩放、卡片文本缩放、减少动态、高对比等</td></tr><tr><td>数据与备份</td><td>缓存、导出、迁移包、存储维护</td></tr><tr><td>高级</td><td>二级锚点：<strong>AI 连接</strong>（provider / 模型 / key）、<strong>存储与性能</strong>、<strong>系统健康与诊断</strong>、<strong>旧版与兼容性</strong>（含 <code>ankiForceDisableJs</code> 等实验开关）</td></tr><tr><td>关于</td><td>版本信息、更新日志、隐私详情</td></tr><tr><td>开发者（Fun Lab）</td><td>仅 debug 构建可见</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">入口位置</p><p>AI 相关设置不在独立分区，在「高级 → AI 连接」；Anki 排期偏好在「学习」页的 Anki 区。没有单牌组覆盖编辑器。</p></div><h2 id="存储维护" tabindex="-1">存储维护 <a class="header-anchor" href="#存储维护" aria-label="Permalink to &quot;存储维护&quot;">​</a></h2><p>存储页区分不可再生成数据和可再生成数据：</p><table tabindex="0"><thead><tr><th>数据</th><th>清理行为</th></tr></thead><tbody><tr><td>课程数据库</td><td>不在普通缓存清理中删除</td></tr><tr><td>Anki Collection / 学习状态</td><td>不在普通缓存清理中删除</td></tr><tr><td>Anki 媒体</td><td>仅通过明确的牌组或媒体维护操作处理</td></tr><tr><td>AI 缓存</td><td>可清理，不删除课程和会话真相源</td></tr><tr><td>日志</td><td>可独立清理，不自动改变系统健康分数</td></tr></tbody></table><p>数据库完整性检查使用只读 <code>PRAGMA integrity_check</code>。索引维护使用 <code>REINDEX</code> 和 <code>PRAGMA optimize</code>。这些操作不得附带删除学习数据。</p><h2 id="系统健康" tabindex="-1">系统健康 <a class="header-anchor" href="#系统健康" aria-label="Permalink to &quot;系统健康&quot;">​</a></h2><p>本地监控（<code>SystemHealthMonitor</code>）按指纹聚合最近 24 小时内的异常日志事件：warning 组计 1 分，error 组计 3 分，fatal 直接把分数钉到严重线。<strong>计分按组不按次数</strong>——同一指纹的重复出现只更新该组计数与最近时间，不重复加分。</p><table tabindex="0"><thead><tr><th style="text-align:right;">分数</th><th>状态</th></tr></thead><tbody><tr><td style="text-align:right;">0–9</td><td>正常</td></tr><tr><td style="text-align:right;">10–39</td><td>需要注意</td></tr><tr><td style="text-align:right;">≥40 或 fatal</td><td>严重</td></tr></tbody></table><p>分数只随时间衰减（组移出 24h 窗口自动不计分）或随事件 7 天无复发自动过期 —— <strong>任何界面操作都不能扣分</strong>。「确认」只标记已读；真正的解除需要「运行自检」（数据库完整性探针 + 重算分数）通过且衰减分 &lt;10。新事件会重新打开警报并作废旧的自检结论。</p><p>另有独立的数据完整性阻断标记（<code>dataIntegrityBlock</code>）：只由有直接数据损坏证据的调用点上报，不从日志分数推导。</p><h2 id="安全模式" tabindex="-1">安全模式 <a class="header-anchor" href="#安全模式" aria-label="Permalink to &quot;安全模式&quot;">​</a></h2><p>安全模式是运行时覆盖，不覆盖已保存偏好，退出后恢复原配置。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/anki-rendering">卡片渲染与网络隔离</a></li><li><a href="/docs/guide/accessibility">可访问性</a></li><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li></ul>',18)])])}const b=d(i,[["render",o]]);export{p as __pageData,b as default};
